//! Keep signed Kiro reasoning for tool continuation within one gateway session.
use std::{collections::BTreeMap,sync::{Mutex,OnceLock},time::{Duration,Instant}};
use serde_json::{json,Value};use sha2::{Digest,Sha256};
struct Entry{context:[u8;32],assistant:Value,reasoning:Value,expires:Instant,size:usize}
static CACHE:OnceLock<Mutex<BTreeMap<String,Entry>>>=OnceLock::new();
fn digest(value:&Value)->Result<[u8;32],String>{Ok(Sha256::digest(serde_json::to_vec(value).map_err(|_|"Historique Kiro invalide.")?).into())}
fn key(session:&str,reference:&str,model:&str,id:&str)->String{let mut hash=Sha256::new();for part in [session,reference,model,id]{hash.update((part.len() as u64).to_be_bytes());hash.update(part.as_bytes())}format!("{:x}",hash.finalize())}
fn clean(cache:&mut BTreeMap<String,Entry>){cache.retain(|_,entry|entry.expires>Instant::now())}
fn context_for_request(request:&Value)->Result<Value,String>{let state=request.get("conversationState").ok_or("Historique Kiro absent.")?;let mut history=state.get("history").and_then(Value::as_array).cloned().ok_or("Historique Kiro invalide.")?;let mut current=state.pointer("/currentMessage/userInputMessage").cloned().ok_or("Demande Kiro invalide.")?;if let Some(context)=current.get_mut("userInputMessageContext").and_then(Value::as_object_mut){context.remove("tools");if context.is_empty(){current.as_object_mut().unwrap().remove("userInputMessageContext");}}history.push(json!({"userInputMessage":current}));Ok(json!(history))}
fn assistant_from_result(result:&Value)->Result<Value,String>{let message=result.pointer("/choices/0/message").ok_or("Réponse Kiro invalide.")?;let calls=message.get("tool_calls").and_then(Value::as_array).filter(|c|!c.is_empty()).ok_or("Appel Kiro absent.")?;let mut uses=Vec::new();for call in calls{let id=call.get("id").and_then(Value::as_str).ok_or("Identifiant Kiro absent.")?;let name=call.pointer("/function/name").and_then(Value::as_str).ok_or("Outil Kiro absent.")?;let input:Value=serde_json::from_str(call.pointer("/function/arguments").and_then(Value::as_str).ok_or("Arguments Kiro absents.")?).map_err(|_|"Arguments Kiro invalides.")?;uses.push(json!({"toolUseId":id,"name":name,"input":input}));}Ok(json!({"content":message.get("content").and_then(Value::as_str).unwrap_or(""),"toolUses":uses}))}
pub fn store(session:&str,reference:&str,model:&str,request:&Value,result:&mut Value)->Result<(),String>{
 let Some(reasoning)=result.as_object_mut().and_then(|o|o.remove("_nivra_kiro_reasoning"))else{return Ok(())};let Some(id)=result.pointer("/choices/0/message/tool_calls/0/id").and_then(Value::as_str)else{return Ok(())};let assistant=assistant_from_result(result)?;let context=digest(&context_for_request(request)?)?;let size=assistant.to_string().len().saturating_add(reasoning.to_string().len());if size>2*1024*1024{return Err("Raisonnement Kiro trop volumineux.".into())}let mut cache=CACHE.get_or_init(||Mutex::new(BTreeMap::new())).lock().map_err(|_|"Historique Kiro indisponible.")?;clean(&mut cache);let key=key(session,reference,model,id);if cache.contains_key(&key){return Err("Identifiant d’outil Kiro déjà utilisé.".into())}while cache.len()>=64||cache.values().map(|v|v.size).sum::<usize>().saturating_add(size)>4*1024*1024{let oldest=cache.iter().min_by_key(|(_,v)|v.expires).map(|(k,_)|k.clone()).ok_or("Historique Kiro saturé.")?;cache.remove(&oldest);}cache.insert(key,Entry{context,assistant,reasoning,expires:Instant::now()+Duration::from_secs(1800),size});Ok(())
}
pub fn restore(session:&str,reference:&str,model:&str,request:&mut Value)->Result<(),String>{
 let history=request.pointer_mut("/conversationState/history").and_then(Value::as_array_mut).ok_or("Historique Kiro invalide.")?;let mut cache=CACHE.get_or_init(||Mutex::new(BTreeMap::new())).lock().map_err(|_|"Historique Kiro indisponible.")?;clean(&mut cache);
 for i in 0..history.len(){let Some(assistant)=history[i].get("assistantResponseMessage")else{continue};let Some(id)=assistant.pointer("/toolUses/0/toolUseId").and_then(Value::as_str)else{continue};let Some(entry)=cache.get(&key(session,reference,model,id))else{continue};if &entry.assistant!=assistant||entry.context!=digest(&json!(history[..i]))?{return Err("La conversation Kiro ne correspond pas à l’appel d’outil signé.".into())}history[i]["assistantResponseMessage"]["reasoningContent"]=entry.reasoning.clone();}Ok(())
}
#[cfg(test)]mod tests{use super::*;
 #[test]fn restores_only_matching_signed_turn(){let mut request=json!({"conversationState":{"history":[],"currentMessage":{"userInputMessage":{"content":"Aide","modelId":"m","origin":"AI_EDITOR","userInputMessageContext":{"tools":[{}]}}}}});let mut result=json!({"choices":[{"message":{"role":"assistant","content":null,"tool_calls":[{"id":"call","type":"function","function":{"name":"read","arguments":"{}"}}]}}],"_nivra_kiro_reasoning":{"reasoningText":{"text":"r","signature":"s"}}});store("session-test","ref","m",&request,&mut result).unwrap();assert!(result.get("_nivra_kiro_reasoning").is_none());request["conversationState"]["history"]=json!([{"userInputMessage":{"content":"Aide","modelId":"m","origin":"AI_EDITOR"}},{"assistantResponseMessage":{"content":"","toolUses":[{"toolUseId":"call","name":"read","input":{}}]}}]);restore("session-test","ref","m",&mut request).unwrap();assert_eq!(request["conversationState"]["history"][1]["assistantResponseMessage"]["reasoningContent"]["reasoningText"]["signature"],"s");let mut changed=request.clone();changed["conversationState"]["history"][0]["userInputMessage"]["content"]=json!("autre");changed["conversationState"]["history"][1]["assistantResponseMessage"].as_object_mut().unwrap().remove("reasoningContent");assert!(restore("session-test","ref","m",&mut changed).is_err());}
}
